 1	method find_min_index(a : array<int>, s: int, e: int) returns (min_i: int)
 2	requires a.Length > 0
 3	requires 0 <= s < a.Length
 4	requires e <= a.Length
 5	requires e > s
 6	
 7	ensures min_i >= s 
 8	ensures min_i < e 
 9	ensures forall k: int :: s <= k < e ==> a[min_i] <= a[k]
10	{
11	    min_i := s;
12	    var i : int := s;  
13	
14	    while i < e 
15	    decreases e - i // loop variant
16	    invariant s <= i <= e
17	    invariant s <= min_i < e
18	    // unnecessary invariant
19	    // invariant i < e ==> min_i <= i 
20	    {
21	        if a[i] <= a[min_i] {
22	            min_i := i;
23	        }
24	        i := i + 1;
25	    }
26	
27	}
28	
29	
30	
31	predicate is_sorted(ss: seq<int>)
32	{
33	    forall i, j: int:: 0 <= i <= j < |ss| ==> ss[i] <= ss[j]
34	}
35	
36	predicate is_permutation(a:seq<int>, b:seq<int>)
37	decreases |a|
38	decreases |b|
39	{
40	    |a| == |b|  && 
41	    ((|a| == 0 && |b| == 0) ||  
42	    exists i,j : int :: 0<=i<|a| &&  0<=j<|b|  && a[i] == b[j] && is_permutation(a[0..i] + if i < |a| then a[i+1..] else [], b[0..j] + if j < |b| then  b[j+1..] else []))
43	}
44	
45	
46	// predicate is_permutation(a:seq<int>, b:seq<int>)
47	// decreases |a|
48	// decreases |b|
49	// {
50	//     |a| == |b|  && ((|a| == 0 && |b| == 0) ||  exists i,j : int :: 0<=i<|a| &&  0<=j<|b|  && a[i] == b[j] && is_permutation(a[0..i] + a[i+1..], b[0..j] + b[j+1..]))
51	// }
52	
53	predicate is_permutation2(a:seq<int>, b:seq<int>)
54	{
55	    multiset(a) == multiset(b)
56	}
57	
58	
59	
60	method selection_sort(ns: array<int>) 
61	requires ns.Length >= 0
62	ensures is_sorted(ns[..])
63	ensures is_permutation2(old(ns[..]), ns[..])
64	modifies ns
65	{
66	    var i: int := 0;
67	    var l: int := ns.Length;
68	    while i < l
69	    decreases l - i
70	    invariant 0 <= i <= l
71	    invariant is_permutation2(old(ns[..]), ns[..])
72	    invariant forall k, kk: int :: 0 <= k < i  && i <= kk < ns.Length ==> ns[k] <= ns[kk] // left els must be lesser than right ones
73	    invariant is_sorted(ns[..i])
74	    {
75	        var min_i: int := find_min_index(ns, i, ns.Length);
76	        ns[i], ns[min_i] := ns[min_i], ns[i];
77	        i := i + 1;
78	    }
79	
80	}

